// Views/_ViewImports.cshtml: @addTagHelper *, MyApp  ==> view: <money amount="@order.Total" />
public class MoneyTagHelper : TagHelper
{
    public decimal Amount { get; set; }  public string Currency { get; set; } = "EUR";
    public override void Process(TagHelperContext ctx, TagHelperOutput output)
    {
        output.TagName = "span";
        output.Attributes.SetAttribute("class", "money");
        output.Content.SetContent(Amount.ToString("C", CultureInfo.GetCultureInfo(Currency)));
    }
}
